function H(e,T,M,h,P=300){const l=M/2,v=h/2,E=Math.min(M,h)/3,a=new Map;e.forEach((f,c)=>{const t=2*Math.PI*c/Math.max(e.length,1);a.set(f,{id:f,x:l+E*Math.cos(t),y:v+E*Math.sin(t)})});const q=5500,w=150,p=.02,u=.01,N=.85,m=new Map;e.forEach(f=>m.set(f,{vx:0,vy:0}));for(let f=0;f<P;f++){const c=new Map;e.forEach(t=>c.set(t,{fx:0,fy:0}));for(let t=0;t<e.length;t++)for(let o=t+1;o<e.length;o++){const s=a.get(e[t]),n=a.get(e[o]),x=s.x-n.x,r=s.y-n.y,y=Math.max(x*x+r*r,1),g=Math.sqrt(y),i=q/y,R=x/g*i,S=r/g*i;c.get(s.id).fx+=R,c.get(s.id).fy+=S,c.get(n.id).fx-=R,c.get(n.id).fy-=S}for(const t of T){const o=a.get(t.source),s=a.get(t.target);if(!o||!s)continue;const n=s.x-o.x,x=s.y-o.y,r=Math.max(Math.sqrt(n*n+x*x),1),y=r-w,g=n/r*y*p,i=x/r*y*p;c.get(o.id).fx+=g,c.get(o.id).fy+=i,c.get(s.id).fx-=g,c.get(s.id).fy-=i}for(const t of e){const o=a.get(t);c.get(t).fx+=(l-o.x)*u,c.get(t).fy+=(v-o.y)*u}for(const t of e){const o=m.get(t),s=c.get(t);o.vx=(o.vx+s.fx)*N,o.vy=(o.vy+s.fy)*N;const n=a.get(t);n.x+=o.vx,n.y+=o.vy}}const G=new Map;return a.forEach((f,c)=>G.set(c,{x:f.x,y:f.y})),G}export{H as c};
